PLACEHOLDER_RE = re.compile(r"\{([^{}]+)\}")
EXPECTED_PLACEHOLDERS = {
    key: set(PLACEHOLDER_RE.findall(value))
    for key, value in FR_EXPECTED.items()
}
MULTILINE_KEYS = {
    "findElements.introHelp",
    "findElements.reviewHelpWithSeverity",
}


def key_pattern(key: str) -> re.Pattern[str]:
    return re.compile(
        rf'(?m)^(?P<indent>[ \t]*)"{re.escape(key)}"\s*:\s*'
        rf'"(?:\\.|[^"\\])*"(?P<comma>,?)\s*$'
    )


def validate_translation_map() -> None:
    expected_locales = set(TARGET_LOCALES)
    actual_locales = set(TRANSLATIONS)
    if actual_locales != expected_locales:
        raise RuntimeError(
            "translation locale mismatch; "
            f"missing={sorted(expected_locales - actual_locales)}, "
            f"extra={sorted(actual_locales - expected_locales)}"
        )

    expected_keys = set(KEYS)
    if set(FR_EXPECTED) != expected_keys:
        raise RuntimeError("internal French source key list mismatch")

    for locale in TARGET_LOCALES:
        mapping = TRANSLATIONS[locale]
        actual_keys = set(mapping)
        if actual_keys != expected_keys:
            raise RuntimeError(
                f"{locale}: key mismatch; "
                f"missing={sorted(expected_keys - actual_keys)}, "
                f"extra={sorted(actual_keys - expected_keys)}"
            )

        for key in KEYS:
            found = set(PLACEHOLDER_RE.findall(mapping[key]))
            expected = EXPECTED_PLACEHOLDERS[key]
            if found != expected:
                raise RuntimeError(
                    f"{locale}: {key} placeholders "
                    f"{sorted(found)} != {sorted(expected)}"
                )

        for key in MULTILINE_KEYS:
            if mapping[key].count("\n") != 2:
                raise RuntimeError(
                    f"{locale}: {key} must contain exactly 3 lines"
                )


def validate_french_source(locale_dir: Path) -> None:
    path = locale_dir / "fr.json"
    if not path.is_file():
        raise RuntimeError(f"missing French locale file: {path}")

    original = path.read_text(encoding="utf-8")
    parsed = json.loads(original)
    if not isinstance(parsed, dict):
        raise RuntimeError("fr.json: top-level JSON value is not an object")

    errors: list[str] = []
    for key in KEYS:
        actual = parsed.get(key)
        expected = FR_EXPECTED[key]
        if actual != expected:
            errors.append(
                f"fr.json: {key!r} does not match the validated French value"
            )

        matches = list(key_pattern(key).finditer(original))
        if len(matches) != 1:
            errors.append(
                f"fr.json: expected exactly one textual occurrence of "
                f"{key!r}, found {len(matches)}"
            )

    if errors:
        raise RuntimeError(
            "French source validation failed. Paste the validated FR block "
            "before running this script:\n- " + "\n- ".join(errors)
        )


def update_locale_text(
    original: str,
    locale: str,
    values: dict[str, str],
    path: Path,
) -> tuple[str, bool]:
    parsed = json.loads(original)
    if not isinstance(parsed, dict):
        raise RuntimeError(f"{path.name}: top-level JSON value is not an object")

    updated = original
    for key in KEYS:
        if key not in parsed:
            raise RuntimeError(f"{path.name}: missing required key {key!r}")

        pattern = key_pattern(key)
        matches = list(pattern.finditer(updated))
        if len(matches) != 1:
            raise RuntimeError(
                f"{path.name}: expected exactly one textual occurrence of "
                f"{key!r}, found {len(matches)}"
            )

        match = matches[0]
        replacement = (
            f'{match.group("indent")}"{key}": '
            f'{json.dumps(values[key], ensure_ascii=False)}'
            f'{match.group("comma")}'
        )
        updated = (
            updated[: match.start()]
            + replacement
            + updated[match.end() :]
        )

    checked = json.loads(updated)
    for key in KEYS:
        if checked.get(key) != values[key]:
            raise RuntimeError(
                f"{path.name}: post-update validation failed for {key!r}"
            )

    return updated, updated != original


def main() -> int:
    repo_root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
    locale_dir = repo_root / "src" / "locales"

    if not locale_dir.is_dir():
        print(
            f"Localization update aborted; locale directory not found: "
            f"{locale_dir}",
            file=sys.stderr,
        )
        return 1

    try:
        validate_translation_map()
        validate_french_source(locale_dir)
    except Exception as exc:
        print(f"Localization update aborted: {exc}", file=sys.stderr)
        return 1

    pending: list[tuple[Path, str]] = []
    errors: list[str] = []
    changed = 0

    for locale in TARGET_LOCALES:
        path = locale_dir / f"{locale}.json"
        if not path.is_file():
            errors.append(f"{path.name}: file not found")
            continue

        try:
            original = path.read_text(encoding="utf-8")
            updated, did_change = update_locale_text(
                original,
                locale,
                TRANSLATIONS[locale],
                path,
            )
            pending.append((path, updated))
            changed += int(did_change)
        except Exception as exc:
            errors.append(str(exc))

    # Fail closed: no locale is written unless all 29 target files validate.
    if errors:
        print(
            "Localization update aborted; no locale file was changed:",
            file=sys.stderr,
        )
        for error in errors:
            print(f"- {error}", file=sys.stderr)
        return 1

    for path, updated in pending:
        path.write_text(updated, encoding="utf-8")

    print(
        f"Updated {len(pending)} non-French locale files with "
        f"{len(KEYS)} revised findElements labels "
        f"({changed} file(s) changed)."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
